import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"PUNTI DI VISTA","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/a_algebra/ad/pvista.md","filePath":"lezioni/a_algebra/ad/pvista.md"}`),a={name:`lezioni/a_algebra/ad/pvista.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="punti-di-vista" tabindex="-1">PUNTI DI VISTA <a class="header-anchor" href="#punti-di-vista" aria-label="Permalink to “PUNTI DI VISTA”">​</a></h1><p>Spesso in matematica si hanno due modi completamente diversi di osservare un fenomeno:</p><ul><li>Il primo è il modo dell&#39;osservatore esterno che descrive un fenomeno.</li><li>Il secondo è la matematica dal punto di vista degli oggetti su cui opera.</li></ul><p>Così abbiamo, per il primo metodo, ad esempio i concetti di somma, differenza, prodotto, quoziente, il significato di parentesi come un tutto unico somma di termini che non posso sommare, il concetto di intervallo in analisi matematica...</p><p>Per il secondo, equivalentemente, abbiamo i concetti di addizione, sottrazione, moltiplicazione, divisione, il significato di parentesi come distribuzione equa dell&#39;operazione esterna, il concetto di intorno in analisi matematica...</p><p>Un altro esempio, che purtroppo è alla base di molti errori, si ha quando consideri un polinomio come:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mn>2</mn><mi>a</mi><mo>−</mo><mn>3</mn><mi>b</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{2a-3b} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord" style="color:red;">2</span><span class="mord mathnormal" style="color:red;">a</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord" style="color:red;">3</span><span class="mord mathnormal" style="color:red;">b</span></span></span></span></span></p><p>Il segno meno nel primo modo indica una sottrazione, nel secondo modo indica il segno del secondo monomio. Molti alunni trascurano questo secondo significato e quindi fanno errori di segno.</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};